<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('overtime.approve');verify_csrf();$pdo=staff_db();$me=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("UPDATE overtime_requests SET status=?,reviewed_by=?,reviewed_at=NOW(),reviewer_notes=? WHERE id=?")->execute([$_POST['decision'],$me['id'],trim($_POST['reviewer_notes']??''),(int)$_POST['id']]);staff_redirect('staff/admin/overtime-approvals.php');}
$rows=$pdo->query("SELECT r.*,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) staff_name,r.reason detail,CONCAT(r.total_hours,' hours') value FROM overtime_requests r JOIN staff s ON s.id=r.staff_id ORDER BY FIELD(r.status,'pending','approved','rejected','cancelled'),r.created_at DESC")->fetchAll();
$pageTitle='Overtime approvals';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Management</p><h1>Overtime approvals</h1></div></div><section class="staff-panel table-panel"><table><thead><tr><th>Staff</th><th>Details</th><th>Value</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['staff_name']) ?></td><td><?= h($r['detail']) ?></td><td><?= h($r['value']) ?></td><td><span class="pill <?= h($r['status']) ?>"><?= h($r['status']) ?></span></td><td><?php if($r['status']==='pending'):?><form method="post" class="decision-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><input name="reviewer_notes" placeholder="Optional note"><button class="btn approve" name="decision" value="approved">Approve</button><button class="btn danger" name="decision" value="rejected">Reject</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>